it.each(['missing-store', 'replaced-git'])(
    'restores Build with its completed Open, evidence and pending Action intact (%s)',
    async (loss) => {
      const f = await fixture();
      for (const file of ['proposal.md', 'design.md', 'tasks.md'])
        await fs.writeFile(
